import { parseInstant, parseRecurrenceRule, plainDate } from '@absoluteui/core';
import { Scheduler, type SchedulerEvent, type SchedulerEventActivateDetail } from '@absoluteui/components/scheduler';

const at = (text: string) => parseInstant(text) ?? parseInstant('1970-01-01T00:00:00Z')!;
const events: SchedulerEvent[] = [
  { id: 'standup', title: 'Standup', start: at('2026-09-28T08:00:00Z'), end: at('2026-09-28T08:15:00Z'), timeZone: 'Europe/London', recurrence: parseRecurrenceRule('FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR') },
  { id: 'review', title: 'Design review', start: at('2026-09-29T13:00:00Z'), end: at('2026-09-29T14:30:00Z'), location: 'Room 4', color: 3 },
  { id: 'offsite', title: 'Offsite', start: plainDate(2026, 10, 1), end: plainDate(2026, 10, 2) },
];
const host = document.createElement('div');
document.body.append(host);
Scheduler.create(host, { label: 'Team calendar', events, timezone: 'Europe/London', date: plainDate(2026, 9, 29) });
host.addEventListener('aui-event-activate', (event) => {
  host.dataset.open = (event as CustomEvent<SchedulerEventActivateDetail>).detail.event.id;
});

import { Scheduler, type SchedulerEvent, type SchedulerEventChangeDetail, type SchedulerSlotActivateDetail } from '@absoluteui/components/scheduler';

const host = document.createElement('div');
document.body.append(host);
const scheduler = Scheduler.create(host, { label: 'Bookings', events: [] as SchedulerEvent[], editable: true, recurringEditScope: 'ask', timezone: 'America/New_York' });
host.addEventListener('aui-event-change', (event) => {
  const { changes } = (event as CustomEvent<SchedulerEventChangeDetail>).detail;
  void fetch('/api/events', { method: 'PATCH', body: JSON.stringify(changes) }).then((r) => {
    if (!r.ok) scheduler.undo();
  }, () => scheduler.undo());
});
host.addEventListener('aui-slot-activate', (event) => {
  const { start, end, resourceId } = (event as CustomEvent<SchedulerSlotActivateDetail>).detail;
  host.dataset.create = JSON.stringify({ start, end, resourceId });
});

import { Scheduler, type SchedulerEvent, type SchedulerLoadErrorDetail } from '@absoluteui/components/scheduler';

const host = document.querySelector<HTMLElement>('#rooms');
if (host) {
  Scheduler.create(host, {
    label: 'Rooms',
    view: 'timeline',
    resources: [{ id: 'r1', label: 'Room 1' }, { id: 'r2', label: 'Room 2', color: 2 }],
    businessCalendar: { workingDays: [1, 2, 3, 4, 5] },
    dayStartHour: 7,
    dayEndHour: 20,
    loadEvents: async (range, signal) => {
      const url = `/api/bookings?from=${encodeURIComponent(new Date(range.start.epochMilliseconds).toISOString())}&to=${encodeURIComponent(new Date(range.end.epochMilliseconds).toISOString())}`;
      const response = await fetch(url, { signal });
      if (!response.ok) throw new Error(`Bookings request failed: ${String(response.status)}`);
      return (await response.json()) as SchedulerEvent[];
    },
  });
  host.addEventListener('aui-load-error', (event) => {
    host.dataset.failed = String((event as CustomEvent<SchedulerLoadErrorDetail>).detail.error);
  });
}
